@RestController @RequestMapping("/api/auth") class SessionEndpoints {
 private final AuthenticationManager manager;private final HttpSessionSecurityContextRepository contexts;private final HttpSessionCsrfTokenRepository tokens;
 SessionEndpoints(AuthenticationManager manager,HttpSessionSecurityContextRepository contexts,HttpSessionCsrfTokenRepository tokens){this.manager=manager;this.contexts=contexts;this.tokens=tokens;}
 private UserDto user(Authentication authentication){boolean admin=authentication.getAuthorities().stream().anyMatch(role->role.getAuthority().equals("ROLE_ADMIN"));return new UserDto(authentication.getName(),authentication.getName(),admin?"admin":"agent");}
 @GetMapping("/csrf") Map<String,String> csrf(CsrfToken token){return Map.of("headerName",token.getHeaderName(),"token",token.getToken());}
 @GetMapping("/me") ResponseEntity<?> me(Authentication authentication){if(authentication==null||authentication instanceof AnonymousAuthenticationToken)return ResponseEntity.status(401).body(ProblemDetail.forStatusAndDetail(HttpStatus.UNAUTHORIZED,"Brak sesji"));return ResponseEntity.ok(user(authentication));}
 @PostMapping("/login") ResponseEntity<?> login(@Valid @RequestBody LoginBody body,HttpServletRequest request,HttpServletResponse response){try{Authentication authentication=manager.authenticate(UsernamePasswordAuthenticationToken.unauthenticated(body.login().trim(),body.password()));new ChangeSessionIdAuthenticationStrategy().onAuthentication(authentication,request,response);new CsrfAuthenticationStrategy(tokens).onAuthentication(authentication,request,response);var context=SecurityContextHolder.createEmptyContext();context.setAuthentication(authentication);SecurityContextHolder.setContext(context);contexts.saveContext(context,request,response);return ResponseEntity.ok(user(authentication));}catch(AuthenticationException error){return ResponseEntity.status(401).body(ProblemDetail.forStatusAndDetail(HttpStatus.UNAUTHORIZED,"Błędny login lub hasło"));}}
 @PostMapping("/logout") ResponseEntity<Void> logout(HttpServletRequest request,HttpServletResponse response,Authentication authentication){new CsrfLogoutHandler(tokens).logout(request,response,authentication);new SecurityContextLogoutHandler().logout(request,response,authentication);new CookieClearingLogoutHandler("SESSION").logout(request,response,authentication);return ResponseEntity.noContent().build();}
