@Service @Transactional class WatchService {
 private final EntityManager manager;private final WatchRepository watches;private final NotificationRepository notifications;private final CommentRepository comments;private final TicketService tickets;private final ApplicationEventPublisher events;
 WatchService(EntityManager manager,WatchRepository watches,NotificationRepository notifications,CommentRepository comments,TicketService tickets,ApplicationEventPublisher events){this.manager=manager;this.watches=watches;this.notifications=notifications;this.comments=comments;this.tickets=tickets;this.events=events;}
 private TicketEntity locked(long id){if(id<0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Nieprawidłowe ID");TicketEntity ticket=manager.find(TicketEntity.class,id,LockModeType.PESSIMISTIC_WRITE);if(ticket==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Nie znaleziono ticketu");return ticket;}
 WatchStatus status(String user,long id){locked(id);return new WatchStatus(watches.findByUserLoginAndTicketId(user,id).isPresent(),watches.countByTicketId(id));}
 WatchStatus set(String user,long id,boolean desired){locked(id);var existing=watches.findByUserLoginAndTicketId(user,id);if(desired&&existing.isEmpty())watches.saveAndFlush(new WatchEntity(user,id));if(!desired&&existing.isPresent()){watches.delete(existing.get());watches.flush();}return new WatchStatus(desired,watches.countByTicketId(id));}
 @PreAuthorize("hasRole('ADMIN')") List<String> watchers(long id){locked(id);return watches.findByTicketId(id).stream().map(watch->watch.userLogin).sorted().toList();}
 PageDto<TicketDto> watched(String user,int page,int size){if(page<1||size<1||size>100)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Nieprawidłowa paginacja");var result=watches.findByUserLogin(user,PageRequest.of(page-1,size,Sort.by("id").descending()));return new PageDto<>(result.getContent().stream().map(watch->tickets.get(watch.ticketId)).toList(),result.getTotalElements(),page,size);}
 private NotificationDto dto(NotificationEntity value){return new NotificationDto(value.id,value.ticketId,value.text,value.createdAt,value.read);}
 List<NotificationDto> notifications(String user,boolean unreadOnly){return notifications.findByUserLoginOrderByIdDesc(user).stream().filter(notification->!unreadOnly||!notification.read).map(this::dto).toList();}
 List<NotificationDto> readThrough(String user,long through){notifications.markThrough(user,through);return notifications(user,false);}
 private void changed(long id,String actor,String text){events.publishEvent(new TicketChanged(id,actor,text,watches.findByTicketId(id).stream().map(watch->watch.userLogin).toList()));}
 TicketDto patch(long id,String actor,JsonNode body){TicketEntity ticket=locked(id);if(!body.isObject()||body.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Brak zmian");for(var fields=body.fieldNames();fields.hasNext();)if(!Set.of("status","assignee","priority","title").contains(fields.next()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Nieznane pole");boolean altered=false;
 if(body.has("status")){if(!body.get("status").isTextual())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Status");TicketStatus status;try{status=TicketStatus.valueOf(body.get("status").asText());}catch(IllegalArgumentException error){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Status");}altered|=ticket.status!=status;ticket.status=status;}
 if(body.has("priority")){if(!body.get("priority").isTextual())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Priority");Priority priority;try{priority=Priority.valueOf(body.get("priority").asText());}catch(IllegalArgumentException error){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Priority");}altered|=ticket.priority!=priority;ticket.priority=priority;}
 if(body.has("title")){if(!body.get("title").isTextual())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Tytuł");String title=body.get("title").asText().trim();if(title.length()<5||title.length()>120)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Tytuł");altered|=!Objects.equals(title,ticket.title);ticket.title=title;}
 if(body.has("assignee")){JsonNode value=body.get("assignee");if(!value.isNull()&&!value.isTextual())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Przypisanie");String assignee=value.isNull()?null:value.asText();if(assignee!=null&&assignee.length()>100)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Przypisanie");altered|=!Objects.equals(ticket.assignee,assignee);ticket.assignee=assignee;}
 if(altered)changed(id,actor,"Zmieniono ticket #"+id);return new TicketDto(ticket.id,ticket.title,ticket.description,ticket.status,ticket.priority,ticket.assignee,ticket.createdAt,List.copyOf(ticket.tags));}
 void comment(long id,String actor,String text){locked(id);var comment=new CommentEntity();comment.ticketId=id;comment.userLogin=actor;comment.text=text.trim();if(comment.text.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Pusty komentarz");comment.createdAt=Instant.now();comments.save(comment);changed(id,actor,"Nowy komentarz w tickecie #"+id);}
 void deleteTicket(long id,String actor){TicketEntity ticket=locked(id);changed(id,actor,"Usunięto ticket #"+id);watches.deleteByTicketId(id);manager.remove(ticket);}
}
@Service class NotificationCreation {private final NotificationRepository notifications;private final ApplicationEventPublisher events;NotificationCreation(NotificationRepository notifications,ApplicationEventPublisher events){this.notifications=notifications;this.events=events;}
 @TransactionalEventListener(phase=TransactionPhase.AFTER_COMMIT) @Transactional(propagation=Propagation.REQUIRES_NEW) public void create(TicketChanged event){var deliveries=new ArrayList<Delivery>();for(String user:new LinkedHashSet<>(event.recipients())){if(user.equals(event.actor()))continue;var value=new NotificationEntity();value.userLogin=user;value.ticketId=event.ticketId();value.text=event.text();value.createdAt=Instant.now();value.read=false;notifications.saveAndFlush(value);deliveries.add(new Delivery(user,new NotificationDto(value.id,value.ticketId,value.text,value.createdAt,false)));}events.publishEvent(new NotificationsCommitted(List.copyOf(deliveries)));}
}
@Component class NotificationStreams {private final ConcurrentMap<String,Set<SseEmitter>> channels=new ConcurrentHashMap<>();SseEmitter subscribe(String user){var emitter=new SseEmitter(300000L);var set=channels.computeIfAbsent(user,key->new CopyOnWriteArraySet<>());set.add(emitter);Runnable remove=()->{set.remove(emitter);if(set.isEmpty())channels.remove(user,set);};emitter.onCompletion(remove);emitter.onTimeout(remove);emitter.onError(error->remove.run());return emitter;}
 @TransactionalEventListener(phase=TransactionPhase.AFTER_COMMIT) public void send(NotificationsCommitted event){for(Delivery delivery:event.deliveries()){var set=channels.get(delivery.user());if(set==null)continue;for(SseEmitter emitter:set){try{emitter.send(SseEmitter.event().id(Long.toString(delivery.notification().id())).name("notification").data(delivery.notification()));}catch(Exception error){set.remove(emitter);emitter.complete();}}}}
 @Scheduled(fixedDelay=15000) public void heartbeat(){channels.forEach((user,set)->{for(SseEmitter emitter:set)try{emitter.send(SseEmitter.event().comment("keepalive"));}catch(Exception error){set.remove(emitter);emitter.complete();}if(set.isEmpty())channels.remove(user,set);});}
}
