@Configuration @EnableMethodSecurity @EnableScheduling class FeatureSecurity {
 @Bean PasswordEncoder passwords(){return new BCryptPasswordEncoder();}
 @Bean UserDetailsService users(PasswordEncoder encoder,@Value("${demo.password:}") String password){if(password.isBlank())throw new IllegalStateException("Ustaw demo.password dla lokalnego ćwiczenia");String encoded=encoder.encode(password);return new InMemoryUserDetailsManager(User.withUsername("anna").password(encoded).roles("AGENT").build(),User.withUsername("piotr").password(encoded).roles("AGENT").build(),User.withUsername("admin").password(encoded).roles("ADMIN").build());}
 @Bean AuthenticationManager manager(UserDetailsService users,PasswordEncoder passwords){var provider=new DaoAuthenticationProvider();provider.setUserDetailsService(users);provider.setPasswordEncoder(passwords);return new ProviderManager(provider);}
 @Bean HttpSessionSecurityContextRepository contexts(){return new HttpSessionSecurityContextRepository();}
 @Bean HttpSessionCsrfTokenRepository csrfTokens(){return new HttpSessionCsrfTokenRepository();}
 @Bean SecurityFilterChain security(HttpSecurity http,AuthenticationManager manager,HttpSessionSecurityContextRepository contexts,HttpSessionCsrfTokenRepository tokens,ObjectMapper mapper)throws Exception {http.authenticationManager(manager).securityContext(config->config.securityContextRepository(contexts)).csrf(config->config.csrfTokenRepository(tokens)).requestCache(config->config.disable()).authorizeHttpRequests(config->config.requestMatchers("/api/auth/**").permitAll().requestMatchers("/api/tickets/*/watchers").hasRole("ADMIN").anyRequest().authenticated()).exceptionHandling(config->config.authenticationEntryPoint((request,response,error)->problem(response,mapper,401,"Zaloguj się")).accessDeniedHandler((request,response,error)->problem(response,mapper,403,"Brak dostępu do operacji")));return http.build();}
 static void problem(HttpServletResponse response,ObjectMapper mapper,int status,String message)throws IOException {response.setStatus(status);response.setContentType("application/problem+json");mapper.writeValue(response.getWriter(),org.springframework.http.ProblemDetail.forStatusAndDetail(HttpStatusCode.valueOf(status),message));}
 @Bean ApplicationRunner seedFeature(TicketService service,TicketRepository repository){return arguments->{if(repository.count()==0){service.create(new CreateTicketRequest("Obserwowany ticket","Zmień status w drugim oknie",Priority.NORMAL,null));service.create(new CreateTicketRequest("Drugi ticket demo","Ćwiczenie paginacji",Priority.HIGH,null));}};}
