const items:NotificationDto[]=[{id:0,ticketId:1,text:"A",createdAt:"2026-11-01T10:00:00Z",read:false},{id:1,ticketId:1,text:"B",createdAt:"2026-11-01T11:00:00Z",read:false},{id:2,ticketId:2,text:"C",createdAt:"2026-11-01T12:00:00Z",read:true}];const next:NotificationDto={id:3,ticketId:1,text:"D",createdAt:"2026-11-01T13:00:00Z",read:false};const watch:WatchStatus={watching:true,count:1};
console.log(notificationSchema.safeParse(items[0]).success);

